// ─── File: ReplicationDemo.java ───
// Runnable demo: leader, followers, ISR, acks=all, leader election.
package com.bank.replication.demo;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class ReplicationDemo {
    private static final Logger log = Logger.getLogger(ReplicationDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Replication factor 3: one leader (broker-1), two followers
        PartitionReplication partition = new PartitionReplication(
                new Replica("broker-1"), new Replica("broker-2"), new Replica("broker-3"));
        ReplicationManager mgr = new ReplicationManager(partition, 2); // min.insync.replicas = 2

        // Write a transfer with acks=all — commits only when ISR has copied it
        mgr.writeAcksAll(new TransferEvent("TXF-1", "SAV2001", "CUR3001", new BigDecimal("50000")));
        mgr.showIsr();

        // broker-3 gets slow and falls out of the ISR
        log.warning(() -> "broker-3 is lagging beyond replica.lag.time.max.ms");
        partition.markLagging("broker-3");
        mgr.writeAcksAll(new TransferEvent("TXF-2", "SAV2001", "CUR3001", new BigDecimal("12000")));
        mgr.showIsr();

        // Leader (broker-1) crashes — elect new leader from the ISR, no data loss
        log.severe(() -> "broker-1 (leader) crashed");
        mgr.electNewLeaderFromIsr();
        mgr.showIsr();
    }
}

