class TransferEvent {
    private final String transferId, fromAccount, toAccount;
    private final BigDecimal amount;
    TransferEvent(String transferId, String fromAccount, String toAccount, BigDecimal amount) {
        this.transferId = transferId; this.fromAccount = fromAccount;
        this.toAccount = toAccount; this.amount = amount;
    }
    String getTransferId() { return transferId; }
    @Override public String toString() {
        return transferId + " " + fromAccount + "->" + toAccount + " " + amount;
    }
}

// ─── Would be in Replica.java ───
class Replica {
    private final String brokerId;
    private final List<TransferEvent> log = new ArrayList<>();
    private boolean lagging = false;
    Replica(String brokerId) { this.brokerId = brokerId; }
    String getBrokerId() { return brokerId; }
    void append(TransferEvent e) { log.add(e); }
    long endOffset() { return log.size(); }
    boolean isLagging() { return lagging; }
    void setLagging(boolean l) { this.lagging = l; }
}

// ─── Would be in PartitionReplication.java ───
class PartitionReplication {
    private Replica leader;
    private final List<Replica> followers = new ArrayList<>();
    private final List<Replica> all = new ArrayList<>();
    PartitionReplication(Replica leader, Replica... followers) {
        this.leader = leader; all.add(leader);
        for (Replica f : followers) { this.followers.add(f); all.add(f); }
    }
    Replica getLeader() { return leader; }
    void setLeader(Replica r) { this.leader = r; followers.remove(r); }
    List<Replica> getFollowers() { return followers; }
    List<Replica> getAll() { return all; }
    void markLagging(String brokerId) {
        all.stream().filter(r -> r.getBrokerId().equals(brokerId))
           .forEach(r -> r.setLagging(true));
    }
    // ISR = leader + followers that are NOT lagging
    List<Replica> isr() {
        List<Replica> isr = new ArrayList<>();
        for (Replica r : all) if (!r.isLagging()) isr.add(r);
        return isr;
    }
}

// ─── Would be in ReplicationManager.java ───
class ReplicationManager {
    private static final Logger log = Logger.getLogger(ReplicationManager.class.getName());
    private final PartitionReplication partition;
    private final int minInSync;
    ReplicationManager(PartitionReplication partition, int minInSync) {
        this.partition = partition; this.minInSync = minInSync;
    }
    void writeAcksAll(TransferEvent e) {
        List<Replica> isr = partition.isr();
        if (isr.size() < minInSync) {
            log.severe(() -> "REJECT write " + e.getTransferId()
                    + " — ISR size " + isr.size() + " < min.insync.replicas " + minInSync);
            return;
        }
        // Leader appends, then all in-sync replicas copy before ack
        for (Replica r : isr) r.append(e);
        log.info(() -> "COMMIT " + e + " acks=all on ISR " + brokerIds(isr));
    }
    void electNewLeaderFromIsr() {
        List<Replica> isr = partition.isr();
        isr.remove(partition.getLeader()); // old leader is gone
        if (isr.isEmpty()) {
            log.severe(() -> "No ISR replica available — would need unclean election (data loss)");
            return;
        }
        Replica newLeader = isr.get(0);
        partition.setLeader(newLeader);
        log.info(() -> "ELECTED new leader " + newLeader.getBrokerId()
                + " from ISR — no committed data lost (endOffset=" + newLeader.endOffset() + ")");
    }
    void showIsr() {
        log.info(() -> "ISR now = " + brokerIds(partition.isr())
                + " leader=" + partition.getLeader().getBrokerId());
    }
    private List<String> brokerIds(List<Replica> rs) {
        List<String> ids = new ArrayList<>();
        for (Replica r : rs) ids.add(r.getBrokerId());
        return ids;
    }
}

